    { type: 'Steps', value: 8543, unit: 'steps', timestamp: '1 min ago', trend: 'up' },
    { type: 'Sleep', value: 7.5, unit: 'hours', timestamp: 'Last night', trend: 'up' },
    { type: 'Activity', value: 45, unit: 'min', timestamp: 'Today', trend: 'stable' },
