'use client';

import { useEffect, useRef } from 'react';
import * as THREE from 'three';

export function NeuralBackground() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      75,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.z = 50;

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setClearColor(0x000000, 0);
    containerRef.current.appendChild(renderer.domElement);

    // Create particles (nodes)
    const particleCount = 150;
    const particles: THREE.Vector3[] = [];
    const particleGeometry = new THREE.BufferGeometry();
    const positions = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
      const x = (Math.random() - 0.5) * 100;
      const y = (Math.random() - 0.5) * 100;
      const z = (Math.random() - 0.5) * 50;

      positions[i * 3] = x;
      positions[i * 3 + 1] = y;
      positions[i * 3 + 2] = z;

      particles.push(new THREE.Vector3(x, y, z));
    }

    particleGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

    // Health-tech gradient colors (orange to red)
    const particleMaterial = new THREE.PointsMaterial({
      color: 0xff6b35,
      size: 0.8,
      transparent: true,
      opacity: 0.6,
      blending: THREE.AdditiveBlending,
    });

    const particleSystem = new THREE.Points(particleGeometry, particleMaterial);
    scene.add(particleSystem);

    // Create neural network connections (lines)
    const lineGeometry = new THREE.BufferGeometry();
    const lineMaterial = new THREE.LineBasicMaterial({
      color: 0xff6b35,
      transparent: true,
      opacity: 0.15,
      blending: THREE.AdditiveBlending,
    });

    const lines: THREE.Line[] = [];
    const maxDistance = 15;

    function updateConnections() {
      // Remove old lines
      lines.forEach(line => scene.remove(line));
      lines.length = 0;

      // Create new connections based on proximity
      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          const distance = particles[i].distanceTo(particles[j]);

          if (distance < maxDistance) {
            const lineGeo = new THREE.BufferGeometry().setFromPoints([
              particles[i],
              particles[j],
            ]);

            const opacity = 1 - (distance / maxDistance);
            const lineMat = new THREE.LineBasicMaterial({
              color: 0xff6b35,
              transparent: true,
              opacity: opacity * 0.15,
              blending: THREE.AdditiveBlending,
            });

            const line = new THREE.Line(lineGeo, lineMat);
            scene.add(line);
            lines.push(line);
          }
        }
      }
    }

    updateConnections();

    // Animation
    let frameCount = 0;
    function animate() {
      requestAnimationFrame(animate);

      // Gentle rotation
      particleSystem.rotation.y += 0.0005;
      particleSystem.rotation.x += 0.0002;

      // Particle wave motion
      const positions = particleGeometry.attributes.position.array as Float32Array;
      for (let i = 0; i < particleCount; i++) {
        const i3 = i * 3;
        positions[i3 + 1] += Math.sin(frameCount * 0.01 + i * 0.1) * 0.02;

        // Update particle vector for connection calculations
        particles[i].set(positions[i3], positions[i3 + 1], positions[i3 + 2]);
      }
      particleGeometry.attributes.position.needsUpdate = true;

      // Update connections every 10 frames for performance
      if (frameCount % 10 === 0) {
        updateConnections();
      }

      frameCount++;
      renderer.render(scene, camera);
    }

    animate();

    // Handle resize
    function handleResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    }

    window.addEventListener('resize', handleResize);

    // Cleanup
    return () => {
      window.removeEventListener('resize', handleResize);
      containerRef.current?.removeChild(renderer.domElement);
      particleGeometry.dispose();
      particleMaterial.dispose();
      renderer.dispose();
    };
  }, []);

  return (
    <div
      ref={containerRef}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        zIndex: 0,
        pointerEvents: 'none',
      }}
    />
  );
}

app/inflamm-ai/page.tsx.content:
'use client';

import React, { useState, useEffect } from 'react';
import { Zap, Activity, MessageCircle, TrendingUp, Edit3, Lock } from 'react-feather';
import { Sidebar } from './components/Sidebar/Sidebar';
import { Header } from './components/Header/Header';
import { WalletGate } from './components/WalletGate/WalletGate';
import { VyTapScreen } from './modules/vytap/VyTapScreen';
import { VitalsyncScreen } from './modules/vitalsync/VitalsyncScreen';
import { ChatScreen } from './modules/chat/ChatScreen';
import { SciCastScreen } from './modules/scicast/SciCastScreen';
import { BlogScreen } from './modules/blog/BlogScreen';
import { WalletConnectionProvider } from './providers/SolanaWalletProvider';
import { TonWalletProvider } from './providers/TonWalletProvider';
import { ParticleBackground } from './components/Background/ParticleBackground';
import { TelegramProvider } from '../components/TelegramProvider';
import './styles/tokens.css';

export default function InflammAIPage() {
  const [activeModule, setActiveModule] = useState('vytap');
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const [showMobileSidebar, setShowMobileSidebar] = useState(false);

  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 1024);
    };
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  useEffect(() => {
    const handleError = (event: ErrorEvent) => {
      const errorMessage = event.message || event.error?.message || '';
      if (
        errorMessage.includes('message channel closed') ||
        errorMessage.includes('Receiving end does not exist') ||
        errorMessage.includes('Extension context invalidated')
      ) {
        event.preventDefault();
        event.stopPropagation();
        return false;
      }
    };

    const handleRejection = (event: PromiseRejectionEvent) => {
      const errorMessage = event.reason?.message || String(event.reason);
      if (
        errorMessage.includes('message channel closed') ||
        errorMessage.includes('Receiving end does not exist') ||
        errorMessage.includes('Extension context invalidated')
      ) {
        event.preventDefault();
        return false;
      }
    };

    window.addEventListener('error', handleError);
    window.addEventListener('unhandledrejection', handleRejection);

    return () => {
      window.removeEventListener('error', handleError);
      window.removeEventListener('unhandledrejection', handleRejection);
    };
  }, []);

  const renderModule = () => {
    switch (activeModule) {
      case 'vytap':
        return (
          <WalletGate>
            <VyTapScreen />
          </WalletGate>
        );
      case 'vitalsync':
        return (
          <WalletGate>
            <VitalsyncScreen />
          </WalletGate>
        );
      case 'chat':
        return (
          <WalletGate>
            <ChatScreen />
          </WalletGate>
        );
      case 'scicast':
        return (
          <WalletGate>
            <SciCastScreen />
          </WalletGate>
        );
      case 'blog':
        return (
          <WalletGate>
            <BlogScreen />
          </WalletGate>
        );
      default:
        return (
          <WalletGate>
            <VyTapScreen />
          </WalletGate>
        );
    }
  };

  return (
    <TelegramProvider>
      <TonWalletProvider>
        <WalletConnectionProvider>
          <ParticleBackground />
          <div className="flex h-screen bg-[var(--bg)] overflow-hidden relative" style={{ zIndex: 10 }}>
        {/* Desktop Sidebar */}
        {!isMobile && (
          <Sidebar
            activeModule={activeModule}
            onNavigate={setActiveModule}
            collapsed={sidebarCollapsed}
          />
        )}

        {/* Mobile Sidebar Overlay */}
        {isMobile && showMobileSidebar && (
          <>
            <div
              className="fixed inset-0 bg-black/60 z-40"
              onClick={() => setShowMobileSidebar(false)}
            />
            <div className="fixed left-0 top-0 bottom-0 z-50">
              <Sidebar
                activeModule={activeModule}
                onNavigate={(module) => {
                  setActiveModule(module);
                  setShowMobileSidebar(false);
                }}
                collapsed={false}
              />
            </div>
          </>
        )}

        {/* Main content */}
        <div className="flex-1 flex flex-col overflow-hidden relative z-10">
          <Header
            onToggleSidebar={() => setShowMobileSidebar(!showMobileSidebar)}
            sidebarCollapsed={sidebarCollapsed}
          />

          <main className="flex-1 overflow-y-auto relative z-10">
            {renderModule()}
          </main>

          {/* Mobile bottom navigation */}
          {isMobile && (
            <nav className="fixed bottom-0 left-0 right-0 bg-[var(--surface)] border-t border-gray-800 z-30">
              <div className="flex justify-around h-16">
                {[
                  { id: 'vytap', label: 'VyTap', Icon: Zap, locked: false },
                  { id: 'vitalsync', label: 'Vitals', Icon: Activity, locked: true },
                  { id: 'chat', label: 'Chat', Icon: MessageCircle, locked: true },
                  { id: 'scicast', label: 'SciCast', Icon: TrendingUp, locked: true },
                  { id: 'blog', label: 'Blog', Icon: Edit3, locked: false },
                ].map((item) => (
                  <button
                    key={item.id}
                    onClick={() => !item.locked && setActiveModule(item.id)}
                    disabled={item.locked}
                    className={`flex flex-col items-center justify-center flex-1 transition-colors relative ${
                      item.locked 
                        ? 'text-gray-600 opacity-50 cursor-not-allowed'
                        : activeModule === item.id
                        ? 'text-[var(--accent-orange)]'
                        : 'text-[var(--muted)]'
                    }`}
                    style={{ minHeight: 'var(--touch-target-min)' }}
                  >
                    {item.locked ? (
                      <>
                        <Lock size={20} className="mb-1" />
                        <span className="text-xs font-medium">{item.label}</span>
                        <span className="absolute -top-1 -right-1 bg-orange-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">
                          Soon
                        </span>
                      </>
                    ) : (
                      <>
                        <item.Icon size={20} className="mb-1" />
                        <span className="text-xs font-medium">{item.label}</span>
                      </>
                    )}
                  </button>
                ))}
              </div>
            </nav>
          )}
        </div>
      </div>
        </WalletConnectionProvider>
      </TonWalletProvider>
    </TelegramProvider>
  );
}

app/globals.css.content:
@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --beige: #FFF9F3;
  --dark-gray: #D84315;
  --muted-gray: #FF6F00;
  --primary-orange: #FF9800;
  --accent-orange: #FFB74D;
}

body {
  background-color: var(--beige);
  color: var(--dark-gray);
}

/* Ensure Solana wallet adapter modal is visible */
.wallet-adapter-modal-wrapper {
  z-index: 99999 !important;
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
}

.wallet-adapter-modal-overlay {
  z-index: 99998 !important;
  background-color: rgba(0, 0, 0, 0.5) !important;
}

.wallet-adapter-modal {
  z-index: 99999 !important;
  display: block !important;
}

.wallet-adapter-modal-container {
