'use client';

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useWallet } from '@solana/wallet-adapter-react';

interface VitalPointsBadgeProps {
  className?: string;
}

export const VitalPointsBadge: React.FC<VitalPointsBadgeProps> = ({ className = '' }) => {
  const { publicKey, connected } = useWallet();
  const [balance, setBalance] = useState<number>(0);
  const [isLoading, setIsLoading] = useState(false);
  const [recentIncrease, setRecentIncrease] = useState<number | null>(null);
  const [isAnimating, setIsAnimating] = useState(false);

  useEffect(() => {
    if (connected && publicKey) {
      fetchBalance();
    } else {
      setBalance(0);
      setIsLoading(false);
    }
  }, [connected, publicKey]);

  const fetchBalance = async () => {
    if (!publicKey) return;

    setIsLoading(true);
    try {
      const walletAddress = publicKey.toString();
      const response = await fetch(`/api/vytap/leaderboard?walletAddress=${walletAddress}`);
      const data = await response.json();

      if (data.success) {
        const userPoints = data.data.userPoints || 0;
        setBalance(userPoints);
      } else {
        setBalance(0);
      }
      setIsLoading(false);
    } catch (error) {
      console.error('Failed to fetch vital points balance:', error);
      setBalance(0);
      setIsLoading(false);
    }
  };

  const updateBalance = (newBalance: number) => {
    const increase = newBalance - balance;
    if (increase > 0) {
      setRecentIncrease(increase);
      setTimeout(() => setRecentIncrease(null), 2000);
    }
    setBalance(newBalance);
  };

  const incrementBalance = (delta: number) => {
    if (delta > 0) {
      setRecentIncrease(delta);
      setTimeout(() => setRecentIncrease(null), 2000);
      // Trigger heartbeat animation
      setIsAnimating(true);
      setTimeout(() => setIsAnimating(false), 400);
    }
    setBalance(prev => prev + delta);
  };

  // Expose updateBalance and incrementBalance for external use
  useEffect(() => {
    (window as any).__updateVitalPoints = updateBalance;
    (window as any).__incrementVitalPoints = incrementBalance;
    return () => {
      delete (window as any).__updateVitalPoints;
      delete (window as any).__incrementVitalPoints;
    };
  }, [balance]);

  return (
    <div className={`relative ${className}`}>
      <motion.div
        className="flex items-center gap-2 px-4 py-2 rounded-lg bg-gradient-to-r from-[var(--accent-orange)] to-[var(--accent-yellow)] text-white font-semibold shadow-lg"
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.98 }}
      >
        <div className="relative w-5 h-5">
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"
              fill="currentColor"
            />
          </svg>

          {isAnimating && (
            <svg
              className="absolute inset-0 pointer-events-none"
              width="20"
              height="20"
              viewBox="0 0 24 24"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <motion.path
                d="M3 12 L6 12 L7.5 8 L9 16 L10.5 12 L12 12 L13.5 9 L15 15 L16.5 12 L18 12 L21 12"
                stroke="var(--accent-orange)"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                fill="none"
                initial={{ pathLength: 0, opacity: 1 }}
                animate={{ pathLength: 1, opacity: 0.8 }}
                transition={{ duration: 0.4, ease: "easeOut" }}
              />
              <motion.path
                d="M3 12 L6 12 L7.5 8 L9 16 L10.5 12 L12 12 L13.5 9 L15 15 L16.5 12 L18 12 L21 12"
                stroke="var(--accent-yellow)"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
                fill="none"
                initial={{ pathLength: 0, opacity: 1 }}
                animate={{ pathLength: 1, opacity: 0.6 }}
                transition={{ duration: 0.4, ease: "easeOut", delay: 0.05 }}
              />
            </svg>
          )}
        </div>

        {isLoading ? (
          <span className="text-sm">...</span>
        ) : (
          <span className="text-sm tabular-nums">
            {(balance ?? 0).toLocaleString()}
          </span>
        )}
      </motion.div>

      <AnimatePresence>
        {recentIncrease && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: -30 }}
            exit={{ opacity: 0 }}
            className="absolute top-0 left-1/2 -translate-x-1/2 text-[var(--accent-yellow)] font-bold text-sm whitespace-nowrap pointer-events-none"
          >
            +{recentIncrease}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

app/api/news/route.ts.content:
import { NextResponse } from 'next/server';

// Using NewsAPI.org - better health category support
const API_URL = "https://newsapi.org/v2/top-headlines";
const API_KEY = process.env.NEWS_API_KEY;

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    // NewsAPI allows up to 100
    const requestedLimit = parseInt(searchParams.get('limit') || '10');
    const limit = Math.min(requestedLimit, 20);

    console.log('🔑 API_KEY status:', API_KEY ? 'Set' : 'Not set');

    if (!API_KEY || API_KEY === 'your_api_key_here') {
      console.error('❌ API key not configured in environment variables');
      return NextResponse.json(
        { error: 'API key not configured. Add NEWS_API_KEY to .env.local' },
        { status: 500 }
      );
    }

    // Use health category and search for additional filtering
    const apiUrl = `${API_URL}?category=health&language=en&pageSize=${limit}&apiKey=${API_KEY}`;
    console.log('📡 Fetching from NewsAPI:', apiUrl.replace(API_KEY, 'HIDDEN'));

    const response = await fetch(apiUrl);

    console.log('📥 Response status:', response.status);

    if (!response.ok) {
      const errorText = await response.text();
      console.error('❌ External API Error:', response.status, errorText);
      return NextResponse.json(
        { error: `External API error: ${response.status} - ${errorText}` },
        { status: response.status }
      );
    }

    const data = await response.json();
    console.log('✅ Received data:', data.articles ? `${data.articles.length} articles` : 'No articles field');

    if (!data.articles || !Array.isArray(data.articles)) {
      console.error('❌ Invalid response structure:', data);
      return NextResponse.json(
        { error: 'Invalid response from news API' },
        { status: 500 }
      );
    }

    const articles = data.articles.map((a: any) => ({
      id: a.url,
      title: a.title,
      summary: a.description || '',
      image: a.urlToImage || '',
      publishedAt: a.publishedAt,
      source: a.source?.name || 'Unknown',
      link: a.url,
    }));

    console.log('✅ Successfully processed', articles.length, 'articles');
    return NextResponse.json({ articles });
  } catch (error) {
    console.error('❌ News API catch block error:', error);
    return NextResponse.json(
      { error: `Server error: ${error instanceof Error ? error.message : 'Unknown error'}` },
      { status: 500 }
    );
  }
}

