    if (typeof window !== 'undefined') {
      const isInTelegram = !!(window as any).Telegram?.WebApp?.initData;
      setIsTelegram(isInTelegram);

      if (isInTelegram) {
        setSelectedWallet('ton');
      }
    }
  }, []);

  // If user is bound, lock to their bound wallet type
  useEffect(() => {
    if (isBound && binding) {
      setSelectedWallet(binding.walletType);
    }
  }, [isBound, binding]);

  if (!mounted) {
    return <div className="h-10 w-32" />;
  }

  // Non-Telegram users: only show Solana wallet
  if (!isTelegram) {
    return <WalletConnectionStatus />;
  }

  // Telegram users: show TON/Solana wallet toggle (unless bound)
  return (
    <div className="flex flex-col gap-3">
      {/* Wallet Type Selector - hide if user is already bound to a wallet */}
      {!isBound && (
        <div className="flex gap-2 p-1 bg-gray-800 rounded-lg">
          <button
            onClick={() => setSelectedWallet('ton')}
            className={`flex-1 px-4 py-2 rounded-md text-sm font-semibold transition-colors ${
              selectedWallet === 'ton'
                ? 'bg-blue-600 text-white'
                : 'text-gray-400 hover:text-white'
            }`}
          >
            TON Wallet
          </button>
          <button
            onClick={() => setSelectedWallet('solana')}
            className={`flex-1 px-4 py-2 rounded-md text-sm font-semibold transition-colors ${
              selectedWallet === 'solana'
                ? 'bg-purple-600 text-white'
                : 'text-gray-400 hover:text-white'
            }`}
          >
            Solana Wallet
          </button>
        </div>
      )}

      {/* Wallet Connection UI */}
      <div className="flex justify-center">
        {selectedWallet === 'ton' ? (
          <TonWalletButtonWithModal />
        ) : (
          <WalletConnectionStatus />
        )}
      </div>

      {/* Helper Text */}
      {selectedWallet === 'ton' && (
        <div className="flex flex-col gap-1">
          <p className="text-xs text-center text-gray-400">
            Connect TON wallet via TonConnect protocol
          </p>
          <div className="flex items-center justify-center gap-2 px-3 py-2 bg-blue-900/20 border border-blue-800/30 rounded-lg">
            <span className="text-lg">💎</span>
            <p className="text-xs text-blue-300">
              Telegram Wallet, Tonkeeper, MyTonWallet supported
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

lib/ton-auth.ts.content:
import { Address, Cell, beginCell, contractAddress, loadStateInit } from '@ton/core';
import { sha256_sync } from '@ton/crypto';
import nacl from 'tweetnacl';
import db from './db';

export interface TonVerifyResult {
  success: boolean;
  walletAddress?: string;
  error?: string;
}

export interface TonConnectProof {
  timestamp: number;
  domain: {
    lengthBytes: number;
    value: string;
  };
  signature: string;
  payload: string;
  state_init?: string;
}

export interface TonProofRequest {
  address: string;
  proof: TonConnectProof;
  publicKey?: string;
}

const PROOF_VALIDITY_SECONDS = 300;

export function isTonAddress(address: string): boolean {
  try {
    Address.parse(address);
    return true;
  } catch {
    return false;
  }
}

async function checkReplayProtection(nonce: string): Promise<{isReplay: boolean; error?: string}> {
  try {
    const result = await db.query(
      'SELECT id FROM ton_proof_nonces WHERE nonce = $1 AND expires_at > NOW()',
      [nonce]
    );
    return { isReplay: result.rows.length > 0 };
  } catch (error) {
    console.error('Replay check database error:', error);
    return { isReplay: false, error: 'Replay protection database unavailable' };
  }
}

async function storeNonce(nonce: string, expirySeconds: number): Promise<boolean> {
  try {
    await db.query(
      `INSERT INTO ton_proof_nonces (nonce, expires_at) 
       VALUES ($1, NOW() + INTERVAL '${expirySeconds} seconds')
       ON CONFLICT (nonce) DO NOTHING`,
      [nonce]
    );
    return true;
  } catch (error) {
    console.error('Failed to store nonce:', error);
    return false;
  }
}

function extractPublicKeyFromStateInit(stateInitBase64: string): Uint8Array | null {
  try {
    const stateInitCell = Cell.fromBase64(stateInitBase64);
    const stateInit = loadStateInit(stateInitCell.beginParse());

    if (!stateInit.data) {
      return null;
    }

    const dataSlice = stateInit.data.beginParse();

    dataSlice.loadUint(32);
    dataSlice.loadUint(32);

    const publicKeyBuffer = dataSlice.loadBuffer(32);
    return new Uint8Array(publicKeyBuffer);
  } catch (error) {
    console.error('Failed to extract public key from state_init:', error);
    return null;
  }
}

function verifyAddressFromStateInit(
  claimedAddress: string,
  stateInitBase64: string
): boolean {
  try {
    const stateInitCell = Cell.fromBase64(stateInitBase64);
    const stateInit = loadStateInit(stateInitCell.beginParse());

    if (!stateInit.code || !stateInit.data) {
      return false;
    }

    const parsedClaimed = Address.parse(claimedAddress);

    const derivedAddress = contractAddress(parsedClaimed.workChain, {
      code: stateInit.code,
      data: stateInit.data
    });

    return derivedAddress.equals(parsedClaimed);
  } catch (error) {
    console.error('Address verification from state_init failed:', error);
    return false;
  }
}

export async function verifyTonProof(
  proofRequest: TonProofRequest,
  expectedDomain: string
): Promise<TonVerifyResult> {
  try {
    const { address, proof } = proofRequest;

    const parsedAddress = Address.parse(address);

    if (proof.domain.value !== expectedDomain) {
      return { 
        success: false, 
        error: `Invalid domain. Expected ${expectedDomain}, got ${proof.domain.value}` 
      };
    }

    const now = Math.floor(Date.now() / 1000);
    const proofAge = now - proof.timestamp;

    if (Math.abs(proofAge) > PROOF_VALIDITY_SECONDS) {
      return { 
        success: false, 
        error: `Proof expired. Age: ${proofAge}s, max: ${PROOF_VALIDITY_SECONDS}s` 
      };
    }

    const nonceKey = `${address}-${proof.payload}-${proof.timestamp}`;
    const replayCheck = await checkReplayProtection(nonceKey);

    if (replayCheck.error) {
      return { 
        success: false, 
        error: replayCheck.error
      };
    }

    if (replayCheck.isReplay) {
      return { 
        success: false, 
        error: 'Proof replay detected. This proof has already been used.' 
      };
    }

    if (!proof.state_init) {
      return { 
        success: false, 
        error: 'state_init is required for secure verification' 
      };
    }

    const addressMatches = verifyAddressFromStateInit(address, proof.state_init);
    if (!addressMatches) {
      return { 
        success: false, 
        error: 'Address does not match state_init. Possible impersonation attempt.' 
      };
    }

    const publicKeyBytes = extractPublicKeyFromStateInit(proof.state_init);
    if (!publicKeyBytes) {
      return { success: false, error: 'Failed to extract public key from state_init' };
    }

    const wc = Buffer.alloc(4);
    wc.writeInt32LE(parsedAddress.workChain);

    const ts = Buffer.alloc(8);
    ts.writeBigUInt64LE(BigInt(proof.timestamp));

    const dl = Buffer.alloc(4);
    dl.writeUInt32LE(proof.domain.lengthBytes);

    let payloadBytes: Buffer;
    try {
      payloadBytes = Buffer.from(proof.payload, 'base64');
    } catch {
      payloadBytes = Buffer.from(proof.payload, 'hex');
    }

    const message = Buffer.concat([
      Buffer.from('ton-proof-item-v2/'),
      wc,
      Buffer.from(parsedAddress.hash),
      dl,
      Buffer.from(proof.domain.value),
      ts,
      payloadBytes
    ]);

    const messageHash = sha256_sync(message);

    const fullMessage = Buffer.concat([
      Buffer.from([0xff, 0xff]),
      Buffer.from('ton-connect'),
      messageHash
    ]);

    const signatureHash = sha256_sync(fullMessage);

    let signatureBytes: Uint8Array;
    try {
      signatureBytes = Buffer.from(proof.signature, 'base64');
    } catch (error) {
      try {
        signatureBytes = Buffer.from(proof.signature, 'hex');
      } catch {
        return { success: false, error: 'Invalid signature encoding' };
      }
    }

    if (signatureBytes.length !== 64) {
      return { success: false, error: 'Invalid signature length (must be 64 bytes)' };
    }

    const verified = nacl.sign.detached.verify(
      signatureHash,
      signatureBytes,
      publicKeyBytes
    );

    if (!verified) {
      return { success: false, error: 'Invalid signature' };
    }

    const nonceStored = await storeNonce(nonceKey, PROOF_VALIDITY_SECONDS);
    if (!nonceStored) {
      return { 
        success: false, 
        error: 'Failed to store nonce. Replay protection unavailable.' 
      };
    }

    return { 
      success: true, 
      walletAddress: parsedAddress.toString({ bounceable: false, testOnly: false })
    };
  } catch (error) {
    console.error('TON proof verification error:', error);
    return { success: false, error: 'TON proof verification failed' };
  }
}

export async function verifyTonSignature(
  walletAddress: string,
  signature: string,
  message: string,
  publicKey?: string
): Promise<TonVerifyResult> {
  return { 
    success: false, 
    error: 'Legacy TON signature verification deprecated. Use verifyTonProof with full TonConnect proof payload.' 
  };
}

lib/telegram-auth.ts.content:
import crypto from 'crypto';

interface TelegramInitData {
  query_id?: string;
  user?: {
    id: number;
    first_name: string;
    last_name?: string;
    username?: string;
    language_code?: string;
    is_premium?: boolean;
  };
  auth_date: number;
  hash: string;
}

/**
 * Validates Telegram Mini App initData using HMAC signature verification
 * According to: https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app
 */
export function validateTelegramInitData(initData: string, botToken: string): TelegramInitData | null {
  try {
    // Parse initData manually - preserve exact encoding for HMAC validation
    const rawParams: Record<string, string> = {};
    const decodedParams: Record<string, string> = {};
    let hash = '';

    // Split by & and parse each key=value pair
    const pairs = initData.split('&');
    for (const pair of pairs) {
      const equalIndex = pair.indexOf('=');
      if (equalIndex === -1) continue;

      const key = pair.substring(0, equalIndex);
      const rawValue = pair.substring(equalIndex + 1);

      if (key === 'hash') {
        hash = rawValue;
      } else if (key) {
        // Store raw (encoded) value for HMAC validation
        rawParams[key] = rawValue;
        // Store decoded value for parsing (handle + as space, then decode percent-encoding)
        decodedParams[key] = decodeURIComponent(rawValue.replace(/\+/g, ' '));
      }
    }

    if (!hash) {
      console.error('No hash in initData');
      return null;
    }

    // Sort parameters alphabetically and create data-check-string using RAW values
    const dataCheckString = Object.keys(rawParams)
      .sort()
      .map(key => `${key}=${rawParams[key]}`)
      .join('\n');

    // Create secret key from bot token
    const secretKey = crypto
      .createHmac('sha256', 'WebAppData')
      .update(botToken)
      .digest();

    // Calculate expected hash
    const expectedHash = crypto
      .createHmac('sha256', secretKey)
      .update(dataCheckString)
      .digest('hex');

    // Verify hash
    if (expectedHash !== hash) {
      console.error('Invalid hash signature', { expected: expectedHash, received: hash });
      return null;
    }

    // Check auth_date (not older than 24 hours) - use decoded params for parsing
    const authDate = parseInt(decodedParams['auth_date'] || '0');
    const now = Math.floor(Date.now() / 1000);
    if (now - authDate > 86400) {
      console.error('initData is too old');
      return null;
    }

    // Parse user data - use decoded params
    const userData = decodedParams['user'];
    if (!userData) {
      console.error('No user data in initData');
      return null;
    }

    const user = JSON.parse(userData);

    return {
      query_id: decodedParams['query_id'] || undefined,
      user,
      auth_date: authDate,
      hash
    };
  } catch (error) {
    console.error('Error validating Telegram initData:', error);
    return null;
  }
}

/**
 * Middleware-style function to extract and validate Telegram user from request
 */
export async function getTelegramUserFromRequest(
  request: Request
): Promise<{ telegramUserId: string; user: any } | null> {
  const authHeader = request.headers.get('X-Telegram-Init-Data');

  if (!authHeader) {
    console.error('No X-Telegram-Init-Data header');
    return null;
  }

  const botToken = process.env.TELEGRAM_BOT_TOKEN;
  if (!botToken) {
    console.error('TELEGRAM_BOT_TOKEN not configured');
    return null;
  }

  const validatedData = validateTelegramInitData(authHeader, botToken);

  if (!validatedData || !validatedData.user) {
    return null;
  }

  return {
    telegramUserId: String(validatedData.user.id),
    user: validatedData.user
  };
}

app/inflamm-ai/hooks/useTelegramWalletBi.content:
import { useState, useEffect } from 'react';

interface WalletBinding {
  walletAddress: string;
  walletType: 'solana' | 'ton';
  boundAt: string;
}

interface WalletProof {
  signature: string;
  message: string;
  publicKey?: string;
  tonProof?: any;
}

interface UseWalletBindingResult {
  isBound: boolean;
  binding: WalletBinding | null;
  isLoading: boolean;
  checkBinding: () => Promise<void>;
  createBinding: (walletAddress: string, walletType: 'solana' | 'ton', proof: WalletProof) => Promise<boolean>;
}

export function useTelegramWalletBinding(): UseWalletBindingResult {
  const [isBound, setIsBound] = useState(false);
  const [binding, setBinding] = useState<WalletBinding | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [telegramUserId, setTelegramUserId] = useState<string | null>(null);

  // Get Telegram user ID on mount
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const webApp = (window as any).Telegram?.WebApp;
      if (webApp?.initDataUnsafe?.user?.id) {
        setTelegramUserId(String(webApp.initDataUnsafe.user.id));
      } else {
        setIsLoading(false); // Not in Telegram, no binding needed
      }
    }
  }, []);

  const checkBinding = async () => {
    if (!telegramUserId) {
      setIsLoading(false);
      return;
    }

    try {
      // Get Telegram initData for authentication
      const webApp = (window as any).Telegram?.WebApp;
      const initData = webApp?.initData;

      if (!initData) {
        console.warn('No Telegram initData available');
        setIsLoading(false);
        return;
      }

      const response = await fetch('/api/wallet/binding', {
        method: 'GET',
        headers: {
          'X-Telegram-Init-Data': initData,
        },
      });

      const data = await response.json();

      setIsBound(data.isBound);
      setBinding(data.binding);
    } catch (error) {
      console.error('Error checking wallet binding:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const createBinding = async (walletAddress: string, walletType: 'solana' | 'ton', proof: WalletProof): Promise<boolean> => {
    if (!telegramUserId) {
      console.warn('Cannot create binding: not in Telegram context');
      return false;
    }

    try {
      // Get Telegram initData for authentication
      const webApp = (window as any).Telegram?.WebApp;
      const initData = webApp?.initData;

      if (!initData) {
        console.warn('No Telegram initData available');
        return false;
      }

      const response = await fetch('/api/wallet/binding', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Telegram-Init-Data': initData,
        },
        body: JSON.stringify({
          walletAddress,
          walletType,
          signature: proof.signature,
          message: proof.message,
          publicKey: proof.publicKey,
          tonProof: proof.tonProof,
        }),
      });

      const data = await response.json();

      if (response.status === 409) {
        // Wallet already bound to different address
        alert(`This Telegram account is already linked to another ${data.boundWallet.type} wallet. You cannot change your wallet once connected.`);
        return false;
      }

      if (response.ok) {
        setIsBound(true);
        setBinding(data.binding);
        return true;
      }

      return false;
    } catch (error) {
      console.error('Error creating wallet binding:', error);
      return false;
    }
  };

  // Check binding on mount
  useEffect(() => {
    if (telegramUserId) {
      checkBinding();
    }
  }, [telegramUserId]);

  return {
    isBound,
    binding,
    isLoading,
    checkBinding,
    createBinding,
  };
}

app/api/wallet/binding/route.ts.content:
import { NextRequest, NextResponse } from 'next/server';
import { query, getClient } from '@/lib/db';
import { getTelegramUserFromRequest } from '@/lib/telegram-auth';
import { verifyWalletSignature } from '@/lib/auth';

export async function GET(req: NextRequest) {
  try {
    // Validate Telegram user from initData
    const telegramUser = await getTelegramUserFromRequest(req);

    if (!telegramUser) {
      return NextResponse.json(
        { error: 'Unauthorized: Invalid Telegram authentication' },
        { status: 401 }
      );
    }

    // Check if this Telegram user has a bound wallet
    const result = await query(
      'SELECT wallet_address, wallet_type, bound_at FROM telegram_wallet_bindings WHERE telegram_user_id = $1',
      [telegramUser.telegramUserId]
    );

    if (result.rows.length === 0) {
      return NextResponse.json({
        isBound: false,
        binding: null
      });
    }

    const binding = result.rows[0];
    return NextResponse.json({
      isBound: true,
      binding: {
        walletAddress: binding.wallet_address,
        walletType: binding.wallet_type,
        boundAt: binding.bound_at
      }
    });
  } catch (error) {
    console.error('Error checking wallet binding:', error);
    return NextResponse.json(
      { error: 'Failed to check wallet binding' },
      { status: 500 }
    );
  }
}

export async function POST(req: NextRequest) {
  const client = await getClient();

  try {
    // Validate Telegram user from initData
    const telegramUser = await getTelegramUserFromRequest(req);

    if (!telegramUser) {
      return NextResponse.json(
        { error: 'Unauthorized: Invalid Telegram authentication' },
        { status: 401 }
      );
    }

    const body = await req.json();
    const { walletAddress, walletType, signature, message, publicKey, tonProof } = body;

    if (!walletAddress || !walletType) {
      return NextResponse.json(
        { error: 'Wallet address and wallet type required' },
        { status: 400 }
      );
    }

    if (!['solana', 'ton'].includes(walletType)) {
      return NextResponse.json(
        { error: 'Invalid wallet type. Must be "solana" or "ton"' },
        { status: 400 }
      );
    }

    // CRITICAL SECURITY: Verify wallet ownership before creating binding
    if (!signature || !message) {
      return NextResponse.json(
        { error: 'Wallet ownership proof required (signature and message)' },
        { status: 400 }
      );
    }

    // Verify the signature proves ownership of the wallet
    const verifyResult = await verifyWalletSignature(
      walletAddress,
      signature,
      message,
      false, // Not a session signature
      publicKey,
      tonProof
    );

    if (!verifyResult.success) {
      return NextResponse.json(
        { error: `Wallet ownership verification failed: ${verifyResult.error}` },
        { status: 401 }
      );
    }

    // Verify wallet type matches
    if (verifyResult.walletType && verifyResult.walletType !== walletType) {
      return NextResponse.json(
        { error: 'Wallet type mismatch between proof and specified type' },
        { status: 400 }
      );
    }

    // Begin transaction to handle race conditions
    await client.query('BEGIN');

    try {
      // Check if this Telegram user already has a binding (with row lock)
      const existingBinding = await client.query(
        'SELECT wallet_address, wallet_type FROM telegram_wallet_bindings WHERE telegram_user_id = $1 FOR UPDATE',
        [telegramUser.telegramUserId]
      );

      if (existingBinding.rows.length > 0) {
        const existing = existingBinding.rows[0];

        // If trying to bind a different wallet, reject
        if (existing.wallet_address !== walletAddress) {
          await client.query('ROLLBACK');
          return NextResponse.json(
            {
              error: 'Wallet already bound',
              message: 'This Telegram account is permanently linked to another wallet. You cannot change your wallet once connected.',
              boundWallet: {
                address: existing.wallet_address,
                type: existing.wallet_type
              }
            },
            { status: 409 }
          );
        }

        // Same wallet, return success
        await client.query('COMMIT');
        return NextResponse.json({
          success: true,
          message: 'Wallet already bound to this account',
          binding: {
            walletAddress: existing.wallet_address,
            walletType: existing.wallet_type
          }
        });
      }

      // Create new binding with INSERT ... ON CONFLICT
      const insertResult = await client.query(
        `INSERT INTO telegram_wallet_bindings (telegram_user_id, wallet_address, wallet_type)
         VALUES ($1, $2, $3)
         ON CONFLICT (telegram_user_id) DO NOTHING
         RETURNING wallet_address, wallet_type`,
        [telegramUser.telegramUserId, walletAddress, walletType]
      );

      // If no rows returned, another concurrent request won - fetch the existing binding
      if (insertResult.rows.length === 0) {
        const concurrentBinding = await client.query(
          'SELECT wallet_address, wallet_type FROM telegram_wallet_bindings WHERE telegram_user_id = $1',
          [telegramUser.telegramUserId]
        );

        const existing = concurrentBinding.rows[0];
        if (existing.wallet_address !== walletAddress) {
          await client.query('ROLLBACK');
          return NextResponse.json(
            {
              error: 'Wallet already bound',
              message: 'This Telegram account is permanently linked to another wallet.',
              boundWallet: {
                address: existing.wallet_address,
                type: existing.wallet_type
              }
            },
            { status: 409 }
          );
        }
      }

      await client.query('COMMIT');

      return NextResponse.json({
        success: true,
        message: 'Wallet successfully bound',
        binding: {
          walletAddress,
          walletType
        }
      });
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    }
  } catch (error) {
    console.error('Error binding wallet:', error);
    return NextResponse.json(
      { error: 'Failed to bind wallet' },
      { status: 500 }
    );
  } finally {
    client.release();
  }
}
